import numpy as np

def kernel(x):
    M, N = x.shape
    result = np.full(M, -np.inf, dtype=np.float32)
    tile_rows = 128
    tile_cols = 512

    for i in range(0, M, tile_rows):
        for j in range(0, N, tile_cols):
            end_row = min(i + tile_rows, M)
            end_col = min(j + tile_cols, N)
            tile = x[i:end_row, j:end_col]

            for row_idx in range(tile.shape[0]):
                row_start = i + row_idx
                current_max = result[row_start]
                for col_idx in range(tile.shape[1]):
                    current_val = tile[row_idx, col_idx]
                    if current_val > current_max:
                        current_max = current_val
                result[row_start] = current_max

    return result

