def kernel(x):
    M, N = x.shape
    out = np.empty((M, N), dtype=np.float32)
    for i0 in range(0, M, 128):
        i1 = min(i0 + 128, M)
        # First pass: compute max and sum
        m = np.full(i1 - i0, -np.inf, dtype=np.float32)
        s = np.zeros(i1 - i0, dtype=np.float64)
        for j0 in range(0, N, 512):
            for j in range(j0, min(j0 + 512, N)):
                m = np.maximum(m, x[i0:i1, j])
                s += np.exp((x[i0:i1, j] - m).astype(np.float64))
        # Second pass: compute softmax
        for j0 in range(0, N, 512):
            for j in range(j0, min(j0 + 512, N)):
                out[i0:i1, j] = np.exp((x[i0:i1, j] - m).astype(np.float64)) / s
    return out

import numpy as np


def kernel(x, g, eps):
    M, N = x.shape
    out = np.empty((M, N), dtype=np.float32)
    for i0 in range(0, M, 128):
        i1 = min(i0 + 128, M)
        # First pass: compute the squared norms
        ss = np.zeros(i1 - i0, dtype=np.float64)
        for j0 in range(0, N, 512):
            j1 = min(j0 + 512, N)
            for j in range(j0, j1):
                col = x[i0:i1, j].astype(np.float64)
                ss += col * col
        rinv = 1.0 / np.sqrt(ss / N + eps)
        # Second pass: compute the output
        for j0 in range(0, N, 512):
            j1 = min(j0 + 512, N)
            for j in range(j0, j1):
                out[i0:i1, j] = x[i0:i1, j] * rinv * g[j]
    return out
